        tuningPotential: [ { stage: "Stage 1", power: "105 - 108 hp", notes: "Tuning a Mono-Motronic 8V engine is entirely pointless. An ECU chip might optimize timing slightly, yielding an imperceptible 5hp gain.", zeroToHundred: "13.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "110 - 115 hp", notes: "Requires a performance exhaust and an aggressive camshaft (e.g., Schrick 268 or 272 degree). The car will idle poorly and the single injector will max out.", zeroToHundred: "13.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Engine Swap)", power: "150 - 200+ hp", notes: "The only logical way to make this car fast is to remove the AAE entirely and swap in a 1.8T (AEB) or a 2.8 V6. The chassis easily supports it.", zeroToHundred: "8.5s", hundredToTwoHundred: "N/A" } ],
