        timingType: "Belt (Toothed timing belt spanning both cylinder heads and the water pump. A highly complex routing system that absolutely requires specialized Audi cam locking tools to set the timing correctly)", injectionType: "Multi-Point Injection (Hella MPFI. A fully electronic injection system. Unlike the 2.8 AAH, the 2.6 ABC does NOT use a Mass Air Flow (MAF) sensor; it relies entirely on a Manifold Absolute Pressure (MAP) sensor inside the ECU)", engineLifespan: "350,000+ km (The iron block V6 is exceptionally robust. Its lifespan is usually only threatened by severe oil leaks, neglected timing belts, or failing catalytic converters)", turboType: "Naturally Aspirated (No turbocharger)", ecuType: "Hella MPFI (An unusual ECU for Audi. It houses the MAP sensor internally, connecting to the intake manifold via a small rubber vacuum hose. If this hose cracks, the car runs terribly)", euroStandard: "Euro 2", maxPowerStockInternals: "250+ hp (The block is strong, but because it is a 12-valve naturally aspirated engine, making significant power requires forced induction or a 2.7T swap)",
        fuelConsumption: { city: "12.5 - 14.0 L/100km", highway: "7.8 - 8.8 L/100km", mixed: "9.5 - 10.8 L/100km", sporty: "15.0+ L/100km" },
        oilSpecification: "VW 502.00 10W-40 Synthetic Blend",
        commonIssues: [ 
            "MAP Sensor Hose Failure: The vacuum hose running from the intake manifold directly into the ECU (to the internal MAP sensor) cracks or fills with oil vapor. Causes extreme over-fueling, black smoke, and stalling.",
            "Valley Pan Oil Leaks: The gasket sealing the block valley under the intake manifold hardens and pours oil down the back of the engine.",
            "Valve Cover Gasket Leaks: Oil heavily leaks from both cylinder heads, dripping onto the hot exhaust manifolds and causing a burning smell.",
            "Intake Manifold Changeover Valves: The plastic internal flaps and external vacuum actuators break, killing low-end torque and top-end breathing.",
            "Heater Core Blockage: The C4 heater matrix clogs or bursts, leaking hot coolant inside the cabin.",
            "Catalytic Converter Failure: The dual ceramic catalytic converters degrade and rattle, eventually collapsing and choking the engine."
        ],
        vulnerabilities: [ 
            "Timing Belt Snap (Interference) - If the complex timing belt snaps, the pistons will smash the valves, destroying both cylinder heads.",
            "Botched Timing Jobs - Because the V6 requires a specific cam locking bar and crank pin, mechanics who use the 'mark and pray' method frequently get the timing wrong, causing the car to run terribly.",
            "ECU Destruction (Oil Contamination) - If the internal MAP sensor hose breaks, oil vapor can be sucked directly into the ECU, potentially shorting the circuit board.",
            "Engine Fire Risk (Oil Leaks) - Severe oil leaks from the valve covers dripping directly onto the blistering hot exhaust manifolds can, in extreme cases, ignite.",
            "Massive Fuel Consumption (MAP Fault) - A faulty MAP reading will cause the Hella ECU to dump fuel endlessly, washing the cylinder walls and destroying the cats."
        ],
        oemPlusUpgrades: [ { name: "Silicone MAP Sensor Hose", description: "Replacing the brittle factory rubber vacuum hose leading to the ECU with a thick-walled silicone hose.", benefit: "Absolutely mandatory. Prevents vacuum leaks and oil contamination from destroying the ECU and ruining fuel trims." }, { name: "Aluminum Valley Pan Gasket", description: "Replacing the factory paper/rubber valley pan gasket with a high-quality metal-reinforced version.", benefit: "Permanently cures the massive V6 oil leak hidden under the intake manifold." }, { name: "High-Flow Catalytic Converters", description: "Replacing the ancient, restrictive factory dual cats with high-flow metallic cores.", benefit: "Restores lost power, improves fuel economy, and slightly deepens the V6 exhaust note." }, { name: "Billet Intake Linkages", description: "Replacing the fragile plastic vacuum arms for the intake manifold changeover system with billet aluminum pieces.", benefit: "Restores low-end torque and prevents the flaps from getting stuck." } ],
        transmission: { manual: { name: "01A - 5-Speed Manual", torqueLimit: "300 Nm (Gearbox)", oilType: "API GL-4 SAE 75W-90", note: "A robust gearbox that transforms the driving experience of the V6 compared to the automatic." }, automatics: [ { name: "01K - 4-Speed Automatic", torqueLimit: "300 Nm", oilType: "ATF VW G 052 162", note: "A very heavy, sluggish torque converter automatic. It severely blunts the performance and worsens the already poor fuel economy. Fluid changes every 60k km are critical." } ] },
