        tuningPotential: [ { stage: "Stage 1", power: "205 - 210 hp", notes: "A chip tune optimizes ignition timing and fueling. The 30V head flows well, but natural aspiration limits gains to a minor bump in throttle response and mid-range torque.", zeroToHundred: "7.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "215 - 225 hp", notes: "Requires a high-flow exhaust system, sports catalytic converters, and a cold air intake. The cost is high for minimal naturally aspirated gains.", zeroToHundred: "7.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Supercharger / 2.7T Swap)", power: "280 - 400+ hp", notes: "Historically, PES G2 supercharger kits pushed these to ~280hp, but they are now extinct. The most reliable and cost-effective way to achieve massive power is to swap the engine entirely for a 2.7T BiTurbo (AGB/APB) from the S4 B5.", zeroToHundred: "5.5s", hundredToTwoHundred: "15.0s" } ],
