        tuningPotential: [ { stage: "Stage 1", power: "140 - 145 hp", notes: "Requires a chip tune. The VNT-15 turbo spools instantly, creating a massive surge of torque (over 300 Nm). This will immediately cause an old factory Dual Mass Flywheel and clutch to slip and shudder violently.", zeroToHundred: "10.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2 (Nozzles & Tune)", power: "155 - 165 hp", notes: "Requires upgrading to .216mm injector nozzles, a custom tune, and a Single Mass Flywheel clutch conversion. The factory VNT-15 turbo is operating at its absolute maximum safe speed here.", zeroToHundred: "9.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Turbo Swap)", power: "180 - 200+ hp", notes: "Requires converting to a larger VNT-17 or GTB1756VK turbo, .232mm nozzles, an upgraded 11mm VP37 pump head, and an FMIC. The iron block handles this easily, turning the old C4 into a genuine sleeper.", zeroToHundred: "7.8s", hundredToTwoHundred: "N/A" } ],
