        tuningPotential: [ { stage: "Stage 1", power: "140 - 145 hp", notes: "Requires desoldering the EPROM chips in the MSA11 ECU. A chip tune safely bumps torque to around 320Nm, effectively bringing the engine up to the power level of the later AEL, though it still has smaller injector nozzles.", zeroToHundred: "10.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2 (Nozzles & Tune)", power: "160 - 170 hp", notes: "Requires upgrading to .216mm injector nozzles (from the AEL or VW T4) and a custom chip tune. The factory wastegate turbo is pushed to its maximum safe limit.", zeroToHundred: "9.5s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Turbo Swap)", power: "200 - 250+ hp", notes: "Requires custom fabrication to fit a VNT turbocharger, writing custom N75 maps, .232+mm nozzles, an upgraded 11mm or 12mm pump head, and an FMIC. The 5-cylinder block handles this easily.", zeroToHundred: "7.5s", hundredToTwoHundred: "N/A" } ],
