            tuningPotential: [ { stage: "Stage 1", power: "135 - 140 hp", notes: "As a naturally aspirated 1.8L engine, tuning potential is practically zero. A Stage 1 ECU remap might optimize the fuel curve and marginally improve throttle response, yielding at best 10-15 hp. It is generally considered a waste of money.", zeroToHundred: "10.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "145 - 150 hp", notes: "Requires a full performance exhaust system, a cold air intake, and a custom tune. The cost vastly outweighs the incredibly minor power gains.", zeroToHundred: "10.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Turbo Conversion)", power: "200 - 250+ hp", notes: "Because the AQE block is highly similar to the 1.8T, it is theoretically possible to bolt on a turbo manifold, turbo, intercooler, and 1.8T ECU. However, it is always cheaper and vastly more reliable to simply swap in a complete 1.8T engine instead.", zeroToHundred: "7.8s", hundredToTwoHundred: "N/A" } ],
