            timingType: "Belt & Chain (Toothed timing belt driving the exhaust camshaft, with an internal chain at the rear of the cylinder head linking the exhaust and intake camshafts. Highly durable when serviced, but the hydraulic chain tensioner is a frequent failure point)", injectionType: "Multi-Point Injection (Bosch Motronic ME7.5. An updated, more advanced fuel injection and engine management system featuring Drive-By-Wire electronic throttle)", engineLifespan: "400,000+ km (The iron block and naturally aspirated 20-valve head are incredibly robust. Lacking the heat and stress of a turbocharger, this engine will last virtually forever if the timing components are maintained)", turboType: "Naturally Aspirated (No turbocharger. Relies entirely on the 5-valve-per-cylinder head to breathe at higher RPMs)", ecuType: "Bosch Motronic ME7.5 (Advanced OBD2 compliant system with electronic throttle control)", euroStandard: "Euro 3", maxPowerStockInternals: "200+ hp (The bottom end is fundamentally similar to the 1.8T blocks, but achieving this power naturally aspirated is impossible. Forced induction conversion is required)",
            fuelConsumption: { city: "11.6 - 12.6 L/100km", highway: "6.6 - 7.5 L/100km", mixed: "8.4 - 9.0 L/100km", sporty: "13.0+ L/100km" },
            oilSpecification: "VW 502.00 10W-40 Synthetic Blend or 5W-40 Fully Synthetic",
            commonIssues: [ 
                "Camshaft Chain Tensioner Failure: The hydraulic tensioner for the rear cam chain loses pressure or its plastic guide pads break. Causes a loud, diesel-like clattering noise from the back of the cylinder head.",
                "Valve Cover Gasket Leaks: The gasket becomes brittle with age and heat, leaking oil down the sides of the block and, more critically, into the spark plug wells, causing misfires.",
                "Vacuum Hose Degradation: The complex web of fabric-braided vacuum hoses and the PCV breather tubes become brittle and crack, leading to massive vacuum leaks, rough idle, and stalling.",
                "Mass Air Flow (MAF) Sensor Failure: The Bosch MAF sensor degrades over time, causing hesitation, poor fuel economy, and a severely fluctuating idle.",
                "Electronic Throttle Body (DBW) Issues: The electronic throttle body can become coked with carbon or its internal potentiometers can fail, leading to EPC lights and limp mode.",
                "Coolant Flange Leaks: The plastic coolant flanges on the side and back of the cylinder head warp over time and leak coolant."
            ],
            vulnerabilities: [ 
                "Valvetrain Destruction (Timing Belt Snap) - This is an interference engine. If the 90,000 km timing belt interval is ignored and the belt snaps, all 20 valves will smash into the pistons.",
                "Valvetrain Destruction (Chain Tensioner Failure) - If the rear cam chain tensioner completely collapses or the chain stretches beyond limits, the cams lose synchronization, bending valves.",
                "Oil Starvation (Clogged Pickup) - While less common than on the turbocharged 1.8T, infrequent oil changes can still sludge up the oil pump pickup tube, starving the top end of oil.",
                "Vacuum Leak Stranding - Severe tearing of the main intake boot or PCV system will draw in massive unmetered air, causing the engine to stall and refuse to idle.",
                "Heater Core Blockage - A common C5 chassis issue. The heater core clogs with silicate buildup, resulting in a total loss of cabin heat.",
                "Catalytic Converter Collapse - At 20+ years old, the original ceramic catalytic converters often collapse internally, choking the engine and causing extreme power loss."
            ],
            oemPlusUpgrades: [ { name: "Silicone Vacuum Hose Overhaul", description: "Replacing the brittle factory fabric-braided vacuum hoses with high-quality, heat-resistant silicone lines.", benefit: "Permanently cures vacuum leaks, ensuring a perfectly smooth idle and restoring lost throttle response." }, { name: "Aluminum Coolant Flanges", description: "Replacing the warped factory plastic coolant flanges with cast aluminum aftermarket versions.", benefit: "Permanently solves the chronic minor coolant leaks at the cylinder head." }, { name: "High-Flow Panel Air Filter", description: "Replacing the restrictive paper air filter with a high-flow washable foam or cotton panel filter.", benefit: "Allows the naturally aspirated 20V head to breathe slightly better at the top of the rev range." }, { name: "PCV Catch Can System", description: "Installing a basic oil catch can between the PCV valve and the intake.", benefit: "Prevents oil vapor from coating the electronic throttle body and intake manifold, ensuring a clean idle." } ],
