            model3DHotspots: [{"label":"Engine Top End / PCV System","x":0.01,"y":0.05,"z":0.41,"critical":true,"details":"Center of the engine bay. Prone to valve cover gasket leaks, cracked PCV hoses (the infamous 'S' hose), and failing push-down ignition coils."},{"label":"Firewall / Heater Core / Cam Chain Tensioner","x":0.04,"y":0.06,"z":0.28,"critical":true,"details":"Firewall area. The hydraulic Cam Chain Tensioner is located at the rear of the 1.8T cylinder head here, prone to failure. Also check for clogged heater core matrix."},{"label":"Right Front Suspension & Brakes","x":0.22,"y":-0.10,"z":0.35,"critical":false,"details":"Multi-link front suspension. Check upper and lower control arm bushings and ball joints, which wear out rapidly on the C5 chassis."},{"label":"Left Rear Suspension & Brakes","x":-0.22,"y":-0.10,"z":-0.34,"critical":false,"details":"Rear axle area. Check for seized brake calipers, worn shock absorbers, and degraded suspension bushings."},{"label":"Right Rear Suspension & Drivetrain","x":0.22,"y":-0.09,"z":-0.33,"critical":false,"details":"Inspect the rear suspension components. On Quattro models, check the rear differential seals and axles for fluid leaks or wear."},{"label":"Rear Exhaust System","x":0.13,"y":-0.09,"z":-0.57,"critical":false,"details":"Right side exhaust section. Inspect mufflers, hangers, and pipes for rust or degradation, especially on older models."}], 
